INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-001', 'Conceitos de Nuvem', 'Which of the following is an advantage of cloud computing compared to on-premises infrastructure?', '["You must forecast and provision capacity months in advance", "You trade variable expense for fixed expense", "You benefit from massive economies of scale", "You are responsible for maintaining physical servers"]', 'C', 2, 'One of AWS’s six advantages of cloud computing is benefiting from massive economies of scale. Because AWS aggregates usage across hundreds of thousands of customers, it achieves lower costs than any individual company could.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q1');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-002', 'Conceitos de Nuvem', 'A company wants to move its on-premises MySQL database to AWS with minimal changes to the application code. Which migration strategy best describes this approach?', '["Refactor", "Rehost", "Replatform", "Repurchase"]', 'C', 2, 'Replatform (lift, tinker, and shift) involves moving to the cloud with minor optimizations — like migrating a self-managed MySQL database to Amazon RDS for MySQL. The application code stays largely the same.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q2');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-003', 'Conceitos de Nuvem', 'Which pillar of the AWS Well-Architected Framework focuses on the ability of a system to recover from infrastructure or service failures?', '["Operational Excellence", "Security", "Reliability", "Performance Efficiency"]', 'C', 2, 'The Reliability pillar focuses on the ability of a workload to perform its intended function correctly and consistently, including recovering from failures and dynamically acquiring resources.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q3');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-004', 'Conceitos de Nuvem', 'What is the primary benefit of the ''elasticity'' feature of cloud computing?', '["Automatically replicate data across multiple regions", "Scale resources up or down based on demand", "Provide dedicated hardware for compliance", "Encrypt data at rest and in transit automatically"]', 'B', 1, 'Elasticity refers to the ability to automatically scale computing resources up when demand increases and down when demand decreases, ensuring you only pay for what you use.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q4');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-005', 'Conceitos de Nuvem', 'A startup wants to deploy a web application without managing any servers, operating systems, or infrastructure. Which AWS service model best fits this requirement?', '["Infrastructure as a Service (IaaS)", "Platform as a Service (PaaS)", "Software as a Service (SaaS)", "Function as a Service (FaaS)"]', 'B', 1, 'PaaS (Platform as a Service), such as AWS Elastic Beanstalk, allows developers to deploy applications without managing the underlying infrastructure or operating systems.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q5');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-006', 'Conceitos de Nuvem', 'Which of the following describes the cloud deployment model where an organization runs some workloads on AWS and some on-premises?', '["Public cloud", "Private cloud", "Hybrid cloud", "Multi-cloud"]', 'C', 2, 'A hybrid cloud deployment connects on-premises infrastructure with cloud resources, allowing workloads to run seamlessly in both environments.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q6');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-007', 'Segurança e Conformidade', 'Under the AWS Shared Responsibility Model, which of the following is the customer’s responsibility?', '["Patching the hypervisor on EC2 host machines", "Physical security of AWS data centers", "Configuring security group rules", "Maintaining the global network infrastructure"]', 'C', 2, 'Configuring security group rules (firewall for EC2 instances) is the customer''s responsibility. AWS manages the physical security and infrastructure underlying the services.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q7');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-008', 'Segurança e Conformidade', 'An organization wants to implement multi-factor authentication (MFA) for their AWS accounts. Which IAM component should they configure first?', '["IAM policies", "IAM roles", "IAM root user", "IAM groups"]', 'C', 2, 'AWS security best practice requires enabling MFA on the root user first, as the root user has unrestricted privileges across all resources in the AWS account.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q8');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-009', 'Segurança e Conformidade', 'Which AWS service provides DDoS protection at no additional cost?', '["AWS WAF", "AWS Shield Standard", "AWS Shield Advanced", "Amazon GuardDuty"]', 'B', 1, 'AWS Shield Standard is automatically included for all AWS customers at no additional cost and protects against common transport and network layer DDoS attacks.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q9');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-010', 'Segurança e Conformidade', 'Which AWS service can automatically discover and protect sensitive data such as personally identifiable information (PII) stored in Amazon S3?', '["Amazon Inspector", "Amazon GuardDuty", "Amazon Macie", "AWS Security Hub"]', 'C', 2, 'Amazon Macie uses machine learning to automatically discover, classify, and protect sensitive data (such as PII or credentials) stored in Amazon S3.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q10');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-011', 'Segurança e Conformidade', 'A company needs to download AWS compliance reports such as SOC 2 and PCI DSS certifications. Which AWS service should they use?', '["AWS Config", "AWS CloudTrail", "AWS Artifact", "AWS Trusted Advisor"]', 'C', 2, 'AWS Artifact is a self-service portal for downloading AWS compliance reports, ISO certifications, SOC reports, and PCI DSS attestations.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q11');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-012', 'Segurança e Conformidade', 'What is the key difference between Security Groups and Network ACLs (NACLs)?', '["Security Groups are stateless; NACLs are stateful", "Security Groups operate at the subnet level; NACLs operate at the instance level", "Security Groups only support allow rules; NACLs support allow and deny rules", "Security Groups are applied to S3 buckets; NACLs are applied to EC2 instances"]', 'C', 2, 'Security Groups only support allow rules and are stateful. Network ACLs (NACLs) operate at the subnet level, are stateless, and support both allow and deny rules.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q12');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-013', 'Segurança e Conformidade', 'Which IAM best practice helps ensure that users have only the permissions they need to perform their job?', '["Principle of Most Privilege", "Principle of Least Privilege", "Role-based authentication", "Multi-region access"]', 'B', 1, 'The Principle of Least Privilege dictates granting only the minimum necessary permissions required to perform specific tasks, minimizing risk.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q13');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-014', 'Segurança e Conformidade', 'Which AWS service provides a centralized view of security alerts and compliance status across multiple AWS accounts?', '["Amazon GuardDuty", "AWS Security Hub", "Amazon Inspector", "AWS CloudTrail"]', 'B', 1, 'AWS Security Hub aggregates, organizes, and prioritizes security findings from multiple AWS services (GuardDuty, Macie, Inspector) in a single dashboard.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q14');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-015', 'Tecnologia e Serviços Cloud', 'Which AWS service allows you to run code in response to events without provisioning or managing servers?', '["Amazon EC2", "AWS Lambda", "Amazon ECS", "AWS Elastic Beanstalk"]', 'B', 1, 'AWS Lambda is a serverless event-driven compute service that runs code automatically in response to events without requiring server management.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q15');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-016', 'Tecnologia e Serviços Cloud', 'A company needs to store infrequently accessed data that must be available within milliseconds when requested. Which S3 storage class is most cost-effective?', '["S3 Standard", "S3 Standard-Infrequent Access (S3 Standard-IA)", "S3 Glacier Flexible Retrieval", "S3 One Zone-IA"]', 'B', 1, 'S3 Standard-IA provides millisecond access for data that is less frequently accessed, offering a lower storage fee than S3 Standard.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q16');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-017', 'Tecnologia e Serviços Cloud', 'Which AWS service provides a managed relational database compatible with MySQL and PostgreSQL that offers up to 5x the performance of standard MySQL?', '["Amazon RDS", "Amazon DynamoDB", "Amazon Aurora", "Amazon Redshift"]', 'C', 2, 'Amazon Aurora is a fully managed, high-performance relational database engine compatible with MySQL and PostgreSQL, delivering up to 5x the throughput of standard MySQL.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q17');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-018', 'Tecnologia e Serviços Cloud', 'A company wants to distribute content to users globally with low latency. Which AWS service should they use?', '["Amazon Route 53", "Amazon CloudFront", "AWS Direct Connect", "Elastic Load Balancing"]', 'B', 1, 'Amazon CloudFront is a Content Delivery Network (CDN) that delivers data, videos, APIs, and applications to global users with low latency via edge locations.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q18');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-019', 'Tecnologia e Serviços Cloud', 'Which AWS service should be used to define infrastructure as code using JSON or YAML templates?', '["AWS CloudWatch", "AWS CloudFormation", "AWS Config", "AWS OpsWorks"]', 'B', 1, 'AWS CloudFormation allows you to model, provision, and manage AWS infrastructure resources as code using declarative JSON or YAML templates.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q19');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-020', 'Tecnologia e Serviços Cloud', 'Which AWS compute service is best suited for running Docker containers without managing the underlying EC2 instances?', '["Amazon EC2", "AWS Lambda", "AWS Fargate", "Amazon Lightsail"]', 'C', 2, 'AWS Fargate is a serverless compute engine for containers that works with ECS and EKS, eliminating the need to provision or manage EC2 servers.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q20');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-021', 'Tecnologia e Serviços Cloud', 'Which AWS service provides recommendations to optimize your AWS environment for cost, performance, security, fault tolerance, and service limits?', '["AWS Config", "AWS CloudTrail", "AWS Trusted Advisor", "AWS Personal Health Dashboard"]', 'C', 2, 'AWS Trusted Advisor analyzes your AWS environment and gives actionable guidance across cost optimization, performance, security, fault tolerance, and service limits.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q21');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-022', 'Tecnologia e Serviços Cloud', 'A company needs a NoSQL database that provides single-digit millisecond performance at any scale. Which service should they choose?', '["Amazon RDS", "Amazon Aurora", "Amazon DynamoDB", "Amazon ElastiCache"]', 'C', 2, 'Amazon DynamoDB is a fully managed NoSQL key-value and document database that delivers consistent, single-digit millisecond latency at scale.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q22');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-023', 'Cobrança, Preços e Suporte', 'A company runs a batch processing job that can be interrupted and restarted without data loss. Which EC2 pricing option would provide the greatest cost savings?', '["On-Demand Instances", "Reserved Instances", "Spot Instances", "Dedicated Hosts"]', 'C', 2, 'Spot Instances allow you to purchase spare EC2 capacity at up to 90% discount compared to On-Demand prices, perfect for fault-tolerant batch workloads.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q23');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-024', 'Cobrança, Preços e Suporte', 'Which AWS support plan provides access to a dedicated Technical Account Manager (TAM)?', '["Developer", "Business", "Enterprise On-Ramp", "Enterprise"]', 'D', 3, 'The Enterprise Support plan provides a designated, dedicated Technical Account Manager (TAM) to assist with proactive architectural planning and operations.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q24');
INSERT INTO questions (id, domain, question, options, correct_option, correct_index, explanation, source) VALUES ('clf-c02-025', 'Cobrança, Preços e Suporte', 'Which AWS tool allows you to create budgets and receive alerts when your AWS costs exceed a defined threshold?', '["AWS Cost Explorer", "AWS Budgets", "AWS Pricing Calculator", "AWS Cost and Usage Report"]', 'B', 1, 'AWS Budgets enables setting custom budgets and automated notifications (via email or SNS) whenever costs or usage exceed specified thresholds.', 'Sailor.sh Blog / AWS CLF-C02 Sample Q25');
